CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'user', UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK(length(display_name)<=100));
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own profile" ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY "Update own profile" ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_user_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',NEW.raw_user_meta_data->>'full_name',''),100)); RETURN NEW; END $$;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_user_profile();
CREATE TABLE public.enquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), phone text NOT NULL CHECK(length(phone) BETWEEN 6 AND 30), event_type text NOT NULL CHECK(length(event_type) BETWEEN 1 AND 100), event_date date NOT NULL, venue text NOT NULL DEFAULT '' CHECK(length(venue)<=200), message text NOT NULL DEFAULT '' CHECK(length(message)<=3000), status text NOT NULL DEFAULT 'new' CHECK(status IN('new','contacted','booked','closed')), notes text NOT NULL DEFAULT '' CHECK(length(notes)<=5000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.enquiries TO authenticated; GRANT ALL ON public.enquiries TO service_role;
ALTER TABLE public.enquiries ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins manage enquiries" ON public.enquiries FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 150), description text NOT NULL DEFAULT '' CHECK(length(description)<=3000), image_url text NOT NULL CHECK(length(image_url)<=2000), published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.projects TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.projects TO authenticated; GRANT ALL ON public.projects TO service_role;
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public published projects" ON public.projects FOR SELECT TO anon,authenticated USING(published);
CREATE POLICY "Admins manage all projects" ON public.projects FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 150), client_name text NOT NULL CHECK(length(client_name) BETWEEN 1 AND 100), phone text NOT NULL DEFAULT '' CHECK(length(phone)<=30), event_date date NOT NULL, venue text NOT NULL DEFAULT '' CHECK(length(venue)<=200), status text NOT NULL DEFAULT 'planning' CHECK(status IN('planning','confirmed','completed','cancelled')), budget numeric(14,2) NOT NULL DEFAULT 0 CHECK(budget>=0), paid numeric(14,2) NOT NULL DEFAULT 0 CHECK(paid>=0 AND paid<=budget), notes text NOT NULL DEFAULT '' CHECK(length(notes)<=5000), enquiry_id uuid REFERENCES public.enquiries(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.events TO authenticated; GRANT ALL ON public.events TO service_role;
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins manage events" ON public.events FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX enquiries_created_at_idx ON public.enquiries(created_at DESC);
CREATE INDEX events_date_idx ON public.events(event_date);
CREATE POLICY "Admins upload project photos" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='project-photos' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins read project photos" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='project-photos' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins delete project photos" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='project-photos' AND public.has_role(auth.uid(),'admin'));